import React, { useState, useEffect } from "react";
import {
  Stack,
  TextField,
  MenuItem,
  Button,
  InputAdornment,
  Typography,
} from "@mui/material";
import { Stars as CoinIcon, MonetizationOn as MoneyIcon } from "@mui/icons-material";
import BaseModal from "../BaseModal";

const CURRENCIES = ["USD", "EUR", "GBP", "AED", "SAR", "PKR", "INR", "CAD", "AUD"];

const textFieldSx = {
  "& .MuiOutlinedInput-root": {
    color: "#fff",
    borderRadius: "14px",
    bgcolor: "rgba(255,255,255,0.03)",
    "& fieldset": { borderColor: "rgba(255, 255, 255, 0.1)" },
    "&:hover fieldset": { borderColor: "rgba(255, 255, 255, 0.2)" },
    "&.Mui-focused fieldset": { borderColor: "#4CC66E", borderWidth: "1.5px" },
  },
  "& .MuiInputLabel-root": { color: "rgba(255,255,255,0.4)", fontSize: "0.9rem" },
  "& .MuiInputLabel-root.Mui-focused": { color: "#4CC66E" },
};

const CoinPlanModal = ({ open, onClose, onSubmit, initialData = null, loading = false }) => {
  const isEdit = !!initialData?.id;
  const [formData, setFormData] = useState({
    coins: "100",
    coinsPrice: "",
    currency: "USD",
  });

  useEffect(() => {
    if (!open) return;
    if (initialData) {
      setFormData({
        coins: String(initialData.coins ?? 1),
        coinsPrice: String(initialData.coinsPrice ?? ""),
        currency: initialData.currency || "USD",
      });
    } else {
      setFormData({ coins: "100", coinsPrice: "", currency: "USD" });
    }
  }, [initialData, open]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const coinsNum = Math.max(1, parseInt(formData.coins, 10) || 0);
  const priceNum = parseFloat(formData.coinsPrice);
  const canSave =
    formData.currency &&
    !Number.isNaN(priceNum) &&
    priceNum >= 0 &&
    coinsNum >= 1 &&
    formData.coins !== "";

  const handleSave = () => {
    if (!canSave) return;
    onSubmit({
      coins: coinsNum,
      coinsPrice: priceNum,
      currency: formData.currency.trim().toUpperCase(),
    });
  };

  const actions = (
    <Stack direction="row" spacing={2} sx={{ mt: 1, width: "100%" }}>
      <Button
        fullWidth
        variant="outlined"
        onClick={onClose}
        disabled={loading}
        sx={{
          color: "rgba(255,255,255,0.6)",
          borderColor: "rgba(255,255,255,0.1)",
          borderRadius: "12px",
          textTransform: "none",
          fontWeight: 600,
          "&:hover": { borderColor: "rgba(255,255,255,0.2)", bgcolor: "rgba(255,255,255,0.05)" },
        }}
      >
        Cancel
      </Button>
      <Button
        fullWidth
        variant="contained"
        onClick={handleSave}
        disabled={loading || !canSave}
        sx={{
          bgcolor: "#4CC66E",
          color: "#fff",
          borderRadius: "12px",
          textTransform: "none",
          fontWeight: 700,
          boxShadow: "0 8px 20px rgba(76,198,110,0.25)",
          "&:hover": { bgcolor: "#45b564" },
          "&.Mui-disabled": { bgcolor: "rgba(76,198,110,0.35)", color: "rgba(255,255,255,0.5)" },
        }}
      >
        {loading ? "Saving…" : isEdit ? "Save plan" : "Create plan"}
      </Button>
    </Stack>
  );

  return (
    <BaseModal
      open={open}
      onClose={onClose}
      title={isEdit ? "Edit coin plan" : "Add coin plan"}
      maxWidth="xs"
      actions={actions}
    >
      <Stack spacing={3} sx={{ py: 1 }}>
        <TextField
          fullWidth
          label="Coin amount"
          name="coins"
          type="number"
          value={formData.coins}
          onChange={handleChange}
          required
          inputProps={{ min: 1 }}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <CoinIcon sx={{ color: "#F5A623", fontSize: 20 }} />
              </InputAdornment>
            ),
          }}
          sx={textFieldSx}
        />

        <TextField
          fullWidth
          label="Total price (user pays)"
          name="coinsPrice"
          type="number"
          value={formData.coinsPrice}
          onChange={handleChange}
          required
          inputProps={{ min: 0, step: "0.01" }}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <MoneyIcon sx={{ color: "#4CC66E", fontSize: 20 }} />
              </InputAdornment>
            ),
            endAdornment: (
              <InputAdornment position="end">
                <Typography sx={{ color: "rgba(255,255,255,0.45)", fontSize: "0.8rem", fontWeight: 600 }}>
                  {formData.currency}
                </Typography>
              </InputAdornment>
            ),
          }}
          sx={textFieldSx}
        />

        <TextField
          fullWidth
          select
          label="Currency"
          name="currency"
          value={formData.currency}
          onChange={handleChange}
          sx={textFieldSx}
        >
          {CURRENCIES.map((c) => (
            <MenuItem key={c} value={c} sx={{ fontSize: "0.875rem" }}>
              {c}
            </MenuItem>
          ))}
        </TextField>

        <Typography sx={{ color: "rgba(255, 255, 255, 0.72)", fontSize: "0.75rem", fontWeight: 500, px: 0.5, lineHeight: 1.5 }}>
          Users pay the total price once to receive the full coin amount for this pack. Per-coin value is{" "}
          {canSave ? `${(priceNum / coinsNum).toFixed(4)} ${formData.currency}` : "-"} each.
        </Typography>
      </Stack>
    </BaseModal>
  );
};

export default CoinPlanModal;
