import { useQuery, useQueryClient } from '@tanstack/react-query';
import { toast } from 'react-hot-toast';
import dayjs from 'dayjs';
import { apiGetJson, BASE_URL } from '../../utils/apiClient';
import {
  extractLegacySingleCoinPrice,
  extractPlansFromListResponse,
} from '../../utils/coinPlansApi';
import { queryKeys } from './queryKeys';

export const useDashboardKpis = (token) =>
  useQuery({
    queryKey: queryKeys.dashboard.kpis,
    queryFn: async () => {
      const json = await apiGetJson('/analytics/kpis', token);
      return json.data?.kpis || null;
    },
    enabled: Boolean(token),
    meta: { errorMessage: 'Connection error while fetching KPIs' },
  });

export const useDashboardUserStats = (token) =>
  useQuery({
    queryKey: queryKeys.dashboard.userStats,
    queryFn: async () => {
      const stats = await apiGetJson('/analytics/users', token);
      return stats.data || null;
    },
    enabled: Boolean(token),
  });

export const useDashboardSubTiers = (token) =>
  useQuery({
    queryKey: queryKeys.dashboard.subTiers,
    queryFn: async () => {
      const tiers = await apiGetJson('/analytics/subscriptions', token);
      return tiers.data || null;
    },
    enabled: Boolean(token),
  });

export const useDashboardGrowth = (token, growthYear) =>
  useQuery({
    queryKey: queryKeys.dashboard.growth(growthYear),
    queryFn: async () => {
      const ts = await apiGetJson('/analytics/users/timeseries', token, {
        group: 'month',
        from: `${growthYear}-01-01`,
        to: `${growthYear}-12-31`,
      });
      return ts.data?.series || [];
    },
    enabled: Boolean(token),
  });

export const useDashboardCoinPlans = (token) =>
  useQuery({
    queryKey: queryKeys.dashboard.coinPlans,
    queryFn: async () => {
      const res = await fetch(`${BASE_URL}/coin-prices`, {
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
      });
      const json = await res.json();
      if (!res.ok || json.error) {
        throw new Error(json.message || 'Could not load coin plans');
      }
      let list = extractPlansFromListResponse(json);
      if (list.length === 0) list = extractLegacySingleCoinPrice(json);
      return list;
    },
    enabled: Boolean(token),
  });

export const useDashboardRecentUsers = (
  token,
  {
    page,
    limit,
    sortBy,
    sortOrder,
    search,
    startDate = dayjs().subtract(10, 'day').format('YYYY-MM-DD'),
    endDate = dayjs().format('YYYY-MM-DD'),
  },
) => {
  const params = {
    page,
    limit,
    sortBy,
    sortOrder,
    search,
    startDate,
    endDate,
  };

  return useQuery({
    queryKey: queryKeys.dashboard.recentUsers(params),
    queryFn: async () => {
      const queryParams = {
        page,
        limit,
        sort_by: sortBy,
        sort_order: sortOrder,
        start_date: startDate,
        end_date: endDate,
      };
      if (search) queryParams.q = search;

      const json = await apiGetJson('/users/with-profile', token, queryParams);
      return {
        users: json.data.users || [],
        total: json.data.pagination?.total || 0,
      };
    },
    enabled: Boolean(token),
    placeholderData: (previous) => previous,
  });
};

export const useInvalidateDashboardQueries = () => {
  const queryClient = useQueryClient();
  return () => {
    queryClient.invalidateQueries({ queryKey: ['dashboard'] });
  };
};

export const handleDashboardQueryError = (error, fallbackMessage) => {
  console.error(error);
  toast.error(error?.message || fallbackMessage);
};
