/**
 * Coin plan helpers  normalizes API shapes for dashboard coin purchase plans.
 * Primary routes: GET/POST/PUT/DELETE `${base}/coin-plans`.
 * Fallback: legacy GET/POST `${base}/coin-prices` (single active price).
 * Field names may vary by backend; extend normalizeCoinPlan when Postman contract is known.
 */

export function normalizeCoinPlan(raw) {
  if (!raw || typeof raw !== "object") return null;
  const id = raw.id ?? raw.plan_id ?? raw.uuid;
  const coins = Math.max(
    1,
    Number(raw.coins ?? raw.coin_amount ?? raw.amount ?? raw.quantity ?? 1) || 1
  );
  const coinsPrice = parseFloat(
    raw.coins_price ?? raw.coinsPrice ?? raw.price ?? raw.unit_price ?? 0
  );
  if (Number.isNaN(coinsPrice) || coinsPrice < 0) return null;
  const currency = String(raw.currency || raw.curr || "USD")
    .trim()
    .toUpperCase()
    .slice(0, 8);
  return { id, coins, coinsPrice, currency };
}

export function extractPlansFromListResponse(json) {
  const d = json?.data;
  if (!d) return [];
  if (Array.isArray(d.plans)) return d.plans.map(normalizeCoinPlan).filter(Boolean);
  if (Array.isArray(d.coin_plans)) return d.coin_plans.map(normalizeCoinPlan).filter(Boolean);
  if (Array.isArray(d.coin_prices)) return d.coin_prices.map(normalizeCoinPlan).filter(Boolean);
  if (Array.isArray(d.items)) return d.items.map(normalizeCoinPlan).filter(Boolean);
  if (Array.isArray(d)) return d.map(normalizeCoinPlan).filter(Boolean);
  return [];
}

export function extractLegacySingleCoinPrice(json) {
  const cp = json?.data?.coin_price;
  if (!cp) return [];
  const plan = normalizeCoinPlan({
    id: cp.id,
    coins: cp.coins ?? 1,
    coins_price: cp.coins_price,
    currency: cp.currency,
  });
  return plan ? [plan] : [];
}

export function buildCoinPlanPayload({ coins, coinsPrice, currency }) {
  return {
    coins: Math.max(1, Number(coins) || 1),
    coinsPrice: parseFloat(coinsPrice),
    currency: String(currency || "USD")
      .trim()
      .toUpperCase()
      .slice(0, 8),
  };
}
