/** Equal columns: minmax(0,1fr) prevents content from blowing column width. */
function gridColumnsForCount(n, tier) {
  if (!n) return "none";
  if (tier === "xs") return "minmax(0, 1fr)";
  if (tier === "sm") {
    if (n === 1) return "minmax(0, 1fr)";
    if (n === 2) return "repeat(2, minmax(0, 1fr))";
    if (n === 3) return "repeat(3, minmax(0, 1fr))";
    return "repeat(2, minmax(0, 1fr))";
  }
  if (n <= 4) return `repeat(${n}, minmax(0, 1fr))`;
  return "repeat(4, minmax(0, 1fr))";
}

/** Span rules when last row has fewer than 4 items (md+ only). */
function getGridItemColumn(n, index) {
  if (n <= 4) return undefined;
  const lastRowStart = Math.floor((n - 1) / 4) * 4;
  const rem = n - lastRowStart;
  if (index < lastRowStart) return undefined;
  if (rem === 1) return "1 / -1";
  if (rem === 2) return "span 2";
  if (rem === 3) {
    const pos = index - lastRowStart;
    if (pos === 0 || pos === 1) return "span 2";
    if (pos === 2) return "1 / -1";
  }
  return undefined;
}

