import React, { memo } from 'react';
import { Box, Typography } from '@mui/material';
import TrendingUpIcon from '@mui/icons-material/TrendingUp';
import TrendingDownIcon from '@mui/icons-material/TrendingDown';


const KpiCard = ({
  title,
  value,
  changePercentage,
  trendDirection,
  prefix = '',
  suffix = '',
  icon,
  iconColor = '#4CC66E',
  iconBg = 'rgba(76, 198, 110, 0.12)',
  onClick,
}) => {
  const isUp = trendDirection === 'up';
  const trendColor = isUp ? '#4CC66E' : '#FF5050';
  const trendBg   = isUp ? 'rgba(76,198,110,0.12)' : 'rgba(255,80,80,0.12)';

  const formattedValue =
    typeof value === 'number'
      ? value >= 1000
        ? value.toLocaleString('en-US')
        : value % 1 !== 0
        ? value.toFixed(1)
        : value.toString()
      : value;

  const absChange = Math.abs(changePercentage).toFixed(1);

  const handleClick = typeof onClick === "function" ? onClick : undefined;

  return (
    <Box
      onClick={handleClick}
      sx={{
        flex: { xs: 'none', sm: '1 1 0' },
        width: { xs: '100%', sm: 'auto' },
        minWidth: 0,
        borderLeft: `6px solid ${iconColor}70`,
        boxSizing: 'border-box',
        bgcolor: '#001e08ff',
        borderRadius: '16px',
        position: 'relative',
        overflow: 'hidden',
        p: '24px',
        transition: 'all 0.3s ease',
        cursor: handleClick ? 'pointer' : 'default',
        '&:hover': {
          borderColor: `${iconColor}`,
          transform: handleClick ? 'translateY(-6px)' : 'translateY(-4px)',
          boxShadow: handleClick ? `0 12px 32px ${iconColor}25` : 'none',
        },
      }}
    >
      {/* Icon at top right */}
      <Box
        sx={{
          position: 'absolute',
          top: '20px',
          right: '20px',
          color: iconColor,
          opacity: 0.8,
        }}
      >
        {React.cloneElement(icon, { sx: { fontSize: '1.4rem' } })}
      </Box>

      {/* Header/Title */}
      <Typography
        sx={{
          fontSize: '0.7rem',
          fontWeight: 700,
          color: {iconColor},
          textTransform: 'uppercase',
          letterSpacing: '0.1em',
          mb: 1.5,
          fontFamily: "'Montserrat', sans-serif",
        }}
      >
        {title}
      </Typography>

      {/* Value and Percentage */}
      <Box sx={{ display: 'flex', alignItems: 'baseline', gap: 1.5, mb: 0.5 }}>
        <Typography
          sx={{
            fontSize: '2.4rem',
            fontWeight: 800,
            color: {iconColor},
            fontFamily: "'Montserrat', sans-serif",
            lineHeight: 1,
            letterSpacing: '-0.02em',
          }}
        >
          {prefix}{formattedValue}
        </Typography>

        <Typography
          sx={{
            fontSize: '0.85rem',
            fontWeight: 700,
            color: trendColor,
            fontFamily: "'Montserrat', sans-serif",
          }}
        >
          {isUp ? '+' : '-'}{absChange}%
        </Typography>
      </Box>

      {/* Comparison label */}
      <Typography
        sx={{
          fontSize: '0.65rem',
          fontWeight: 700,
          color: 'rgba(255, 255, 255, 0.6)',
          textTransform: 'uppercase',
          letterSpacing: '0.05em',
          fontFamily: "'Montserrat', sans-serif",
        }}
      >
        vs last month
      </Typography>
    </Box>
  );
};

export default memo(KpiCard);
