// ─────────────────────────────────────────────────────────────────────────────
// Component
// ─────────────────────────────────────────────────────────────────────────────
const Dashboard = () => {
  const queryClient = useQueryClient();
  const [coinPlanModalOpen, setCoinPlanModalOpen] = useState(false);
  const [coinPlanEditing, setCoinPlanEditing] = useState(null);
  const [isSavingCoinPlan, setIsSavingCoinPlan] = useState(false);
  const [planToDelete, setPlanToDelete] = useState(null);

  // ── Recent Users State ────────────────────────────────────────────────
  const [recentUsersSearch, setRecentUsersSearch]   = useState("");
  const [recentUsersOrderBy, setRecentUsersOrderBy] = useState("created_at");
  const [recentUsersOrder, setRecentUsersOrder]     = useState("desc");
  const [recentUsersPage, setRecentUsersPage]       = useState(0);
  const [recentUsersPerPage, setRecentUsersPerPage] = useState(5);
  const [updatingStatus, setUpdatingStatus]         = useState(null);
  const [userToDelete, setUserToDelete]             = useState(null);
  const [openDeleteModal, setOpenDeleteModal]       = useState(false);
  const [userForNotification, setUserForNotification] = useState(null);
  const [openNotificationModal, setOpenNotificationModal] = useState(false);
  const [isSendingNotification, setIsSendingNotification] = useState(false);
  const [selectedUserForEdit, setSelectedUserForEdit] = useState(null);
  const [openEditModal, setOpenEditModal]           = useState(false);
  const [isUpdatingUser, setIsUpdatingUser]         = useState(false);
  const [userForPasswordReset, setUserForPasswordReset] = useState(null);
  const [openResetPasswordModal, setOpenResetPasswordModal] = useState(false);
  const [isResettingPassword, setIsResettingPassword] = useState(false);

  // ── Analytics charts state (C8/C9/C10) ───────────────────────────────────
  const [growthYear, setGrowthYear] = useState(new Date().getFullYear());

  const token = useSelector((state) => state.auth.token);
  const navigate = useNavigate();

  const {
    data: kpiData = null,
    isLoading: isKpiLoading,
    error: kpiError,
  } = useDashboardKpis(token);

  const { data: userStats = null } = useDashboardUserStats(token);
  const { data: subTiers = null } = useDashboardSubTiers(token);
  const { data: growthSeries = [] } = useDashboardGrowth(token, growthYear);
  const {
    data: coinPlans = [],
    isLoading: isCoinPlansLoading,
    refetch: refetchCoinPlans,
  } = useDashboardCoinPlans(token);

  const {
    data: recentUsersResult,
    isLoading: isRecentUsersLoading,
    refetch: refetchRecentUsers,
  } = useDashboardRecentUsers(token, {
    page: recentUsersPage + 1,
    limit: recentUsersPerPage,
    sortBy: recentUsersOrderBy,
    sortOrder: recentUsersOrder,
    search: recentUsersSearch,
  });

  const recentUsers = recentUsersResult?.users || [];
  const recentUsersTotalCount = recentUsersResult?.total || 0;
  const isLoading = isKpiLoading;

  React.useEffect(() => {
    if (kpiError) {
      toast.error(kpiError.message || "Connection error while fetching KPIs");
    }
  }, [kpiError]);

  const handleOpenAddCoinPlan = () => {
    setCoinPlanEditing(null);
    setCoinPlanModalOpen(true);
  };

  const handleOpenEditCoinPlan = (plan) => {
    setCoinPlanEditing(plan);
    setCoinPlanModalOpen(true);
  };

  const handleSaveCoinPlan = async (form) => {
    if (!token) return;
    const payload = buildCoinPlanPayload(form);
    const isEdit = Boolean(coinPlanEditing?.id);
    setIsSavingCoinPlan(true);
    const toastId = toast.loading(isEdit ? "Updating plan…" : "Creating plan…");
    try {
      const res = await fetch(
        isEdit ? `${BASE_URL}/coin-prices/${coinPlanEditing.id}` : `${BASE_URL}/coin-prices`,
        {
          method: isEdit ? "PATCH" : "POST",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify(payload),
        }
      );
      const json = await res.json().catch(() => ({}));

      if (!res.ok || json.error) {
        throw new Error(json.message || "Failed to save coin plan");
      }

      toast.success(isEdit ? "Plan updated" : "Plan created", { id: toastId });
      setCoinPlanModalOpen(false);
      setCoinPlanEditing(null);
      await refetchCoinPlans();
    } catch (err) {
      console.error(err);
      toast.error(err.message || "Failed to save coin plan", { id: toastId });
    } finally {
      setIsSavingCoinPlan(false);
    }
  };

  const handleConfirmDeletePlan = async () => {
    if (!token || !planToDelete?.id) {
      setPlanToDelete(null);
      return;
    }
    const toastId = toast.loading("Deleting plan…");
    try {
      const res = await fetch(`${BASE_URL}/coin-prices/${planToDelete.id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });
      const json = await res.json().catch(() => ({}));

      if (!res.ok || json.error) {
        throw new Error(json.message || "Delete failed");
      }
      toast.success("Plan removed", { id: toastId });
      setPlanToDelete(null);
      await refetchCoinPlans();
    } catch (err) {
      console.error(err);
      toast.error(err.message || "Could not delete plan", { id: toastId });
    }
  };

  // ── Recent Users  action handlers (same as AllUsers) ────────────────
  const handleStatusUpdate = async (userId, newStatus) => {
    setUpdatingStatus(userId);
    try {
      const apiStatus = newStatus === 'blocked' ? 'inactive' : 'active';
      const res = await fetch(`${BASE_URL}/users/${userId}/account-status`, {
        method: 'PATCH',
        headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: apiStatus }),
      });
      const json = await res.json();
      if (!res.ok || json.error) throw new Error(json.message || 'Failed to update status');
      queryClient.setQueriesData(
        { queryKey: ['dashboard', 'recentUsers'] },
        (existing) => {
          if (!existing?.users) return existing;
          return {
            ...existing,
            users: existing.users.map((u) =>
              u.id === userId ? { ...u, block_status: newStatus === 'blocked' } : u,
            ),
          };
        },
      );
      toast.success(`User is now ${newStatus === 'blocked' ? 'Blocked' : 'Unblocked'}`);
    } catch (err) {
      toast.error(err.message || 'Something went wrong while updating status');
    } finally {
      setUpdatingStatus(null);
    }
  };

  const handleDeleteUser = (user) => { setUserToDelete(user); setOpenDeleteModal(true); };

  const handleConfirmDelete = async () => {
    if (!userToDelete || !token) return;
    const toastId = toast.loading('Deleting user...');
    try {
      const res = await fetch(`${BASE_URL}/users/${userToDelete.id}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      });
      const json = await res.json();
      if (!res.ok || json.error) throw new Error(json.message || 'Failed to delete user');
      toast.success('User deleted successfully', { id: toastId });
      refetchRecentUsers();
    } catch (err) {
      toast.error(err.message || 'Something went wrong while deleting user', { id: toastId });
    } finally {
      setOpenDeleteModal(false);
      setUserToDelete(null);
    }
  };

  const handleOpenNotification = (user) => { setUserForNotification(user); setOpenNotificationModal(true); };

  const handleSendNotification = async (formData) => {
    if (!userForNotification || !token) return;
    setIsSendingNotification(true);
    const toastId = toast.loading('Sending notification...');
    try {
      const payload = {
        title: formData.title, body: formData.message, type: 'custom',
        metadata: {}, send_push: true, user_ids: [userForNotification.id],
      };
      const res = await fetch(`${BASE_URL}/notifications/broadcast-selected`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      const json = await res.json();
      if (!res.ok || json.error) throw new Error(json.message || 'Failed to send notification');
      toast.success('Notification sent successfully', { id: toastId });
      setOpenNotificationModal(false);
      setUserForNotification(null);
    } catch (err) {
      toast.error(err.message || 'Something went wrong while sending notification', { id: toastId });
    } finally {
      setIsSendingNotification(false);
    }
  };

  const handleEditClick = (user) => { setSelectedUserForEdit(user); setOpenEditModal(true); };

  const handleResetPasswordClick = (user) => {
    setUserForPasswordReset(user);
    setOpenResetPasswordModal(true);
  };

  const handleResetPasswordSubmit = async ({ newPassword }) => {
    if (!userForPasswordReset || !token) return;
    setIsResettingPassword(true);
    const toastId = toast.loading('Changing password...');
    try {
      await resetUserPassword(userForPasswordReset.id, newPassword, token);
      toast.success('User password changed successfully', { id: toastId });
      setOpenResetPasswordModal(false);
      setUserForPasswordReset(null);
    } catch (err) {
      console.error('Reset password error:', err);
      toast.error(err.message || 'Something went wrong while changing password', { id: toastId });
    } finally {
      setIsResettingPassword(false);
    }
  };

  const handleEditSubmit = async (formData) => {
    if (!selectedUserForEdit || !token) return;
    setIsUpdatingUser(true);
    const toastId = toast.loading('Updating user details...');
    try {
      const res = await fetch(`${BASE_URL}/users/${selectedUserForEdit.id}/profile`, {
        method: 'PATCH',
        headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
        body: JSON.stringify(formData),
      });
      const json = await res.json();
      if (!res.ok || json.error) throw new Error(json.message || 'Failed to update user');
      toast.success('User updated successfully', { id: toastId });
      setOpenEditModal(false);
      setSelectedUserForEdit(null);
      refetchRecentUsers();
    } catch (err) {
      toast.error(err.message || 'Something went wrong while updating user', { id: toastId });
    } finally {
      setIsUpdatingUser(false);
    }
  };

  const handleRecentUsersSort = (property) => {
    const isAsc = recentUsersOrderBy === property && recentUsersOrder === 'asc';
    setRecentUsersOrder(isAsc ? 'desc' : 'asc');
    setRecentUsersOrderBy(property);
    setRecentUsersPage(0);
  };

  // ── Columns (identical to AllUsers) ──────────────────────────────────
  const recentUsersColumns = useMemo(() => [
    {
      id: 'name',
      label: 'Name',
      sortable: true,
      render: (row) => (
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
          <AvatarView
            src={row.profile?.profile_image}
            alt={row.name}
            previewTitle={row.name}
            sx={{ width: 32, height: 32, bgcolor: '#4CC66E', color: '#000', fontSize: '0.75rem', fontWeight: 700, fontFamily: "'Montserrat', sans-serif", flexShrink: 0 }}
          >
            {!row.profile?.profile_image && row.name?.split(' ').map(n => n[0]).join('').slice(0, 2).toUpperCase()}
          </AvatarView>
          <Box>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
              <Typography sx={{ color: '#FFFFFF', fontSize: '0.8rem', fontFamily: "'Montserrat', sans-serif", fontWeight: 500, lineHeight: 1.2 }}>
                {row.name}
              </Typography>
              {row.is_verified && (
                <Tooltip title="Verified User">
                  <Verified sx={{ color: '#1D9BF0', fontSize: '1rem' }} />
                </Tooltip>
              )}
            </Box>
            <Typography sx={{ color: '#8B8D97', fontSize: '0.7rem', fontFamily: "'Montserrat', sans-serif" }}>
              {row.email}
            </Typography>
          </Box>
        </Box>
      ),
    },
    {
      id: 'block_status',
      label: 'Status',
      sortable: true,
      render: (row) => (
        <StatusDropdown
          status={row.block_status ? 'blocked' : 'unblocked'}
          options={[
            { label: 'Unblock', value: 'unblocked', color: '#4CC66E' },
            { label: 'Block',   value: 'blocked',   color: '#FF5050' },
          ]}
          onStatusChange={(newStatus) => handleStatusUpdate(row.id, newStatus)}
          isLoading={updatingStatus === row.id}
        />
      ),
    },
    {
      id: 'plan',
      label: 'Plan',
      render: (row) => {
        const plan = row.profile?.plan_key;
        if (!plan) return <Typography sx={{ fontSize: '1rem' }}>Free</Typography>;
        const label = plan.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
        return (
          <DisplayChip label={label} size="small" sx={{ bgcolor: 'rgba(159,110,218,0.15)', color: '#9F6EDA', fontWeight: 600, fontSize: '0.72rem', borderRadius: '6px' }} />
        );
      },
    },
    {
      id: 'created_at',
      label: 'Signed Up',
      sortable: true,
      render: (row) => (
        <Typography sx={{ color: '#8B8D97', fontSize: '0.8rem', fontFamily: "'Montserrat', sans-serif" }}>
          {row.created_at ? dayjs(row.created_at).format('DD MMM YYYY') : '-'}
        </Typography>
      ),
    },
    {
      id: 'last_logged_in',
      label: 'Last Logged In',
      sortable: true,
      render: (row) => {
        const val = row.last_login || row.last_logged_in || row.lastLogin || row.lastLoggedIn || row.last_seen || row.updated_at || row.profile?.last_login || '';
        return (
          <Typography sx={{ color: '#8B8D97', fontSize: '0.8rem', fontFamily: "'Montserrat', sans-serif" }}>
            {val && dayjs(val).isValid() ? dayjs(val).format('DD MMM YYYY, HH:mm') : '-'}
          </Typography>
        );
      },
    },
  // eslint-disable-next-line react-hooks/exhaustive-deps
  ], [updatingStatus]);

  // ── Chart data (C8/C9/C10) ───────────────────────────────────────────────
  const growthChartData = useMemo(
    () =>
      (growthSeries || []).map((row) => ({
        month: row.period_start ? dayjs(row.period_start).format("MMM") : (row.label || "-"),
        value: row.count || 0,
      })),
    [growthSeries]
  );

  const userBreakdownData = useMemo(() => {
    if (!userStats) return [];
    return [
      { name: "Verified", value: userStats.verified_users || 0, color: "#4CC66E" },
      { name: "Unverified", value: userStats.unverified_users || 0, color: "#F59E0B" },
      { name: "Blocked", value: userStats.blocked_users || 0, color: "#FF5050" },
      { name: "Deleted", value: userStats.deleted_users || 0, color: "#9F6EDA" },
    ].filter((d) => d.value > 0);
  }, [userStats]);

  const subscriptionTierData = useMemo(() => {
    if (!subTiers) return [];
    return [
      { name: "Free Users", value: subTiers.free_users || 0, color: "#4CC66E" },
      { name: "Paid Users", value: subTiers.paid_users || 0, color: "#9F6EDA" },
    ].filter((d) => d.value > 0);
  }, [subTiers]);

  return (
    <Box
      sx={{
        p: { xs: "20px 16px", sm: "28px", md: "36px" },
        minHeight: "100vh",
        position: "relative",
        background: "linear-gradient(135deg, #0F0F10 0%, #1A1A1C 100%)",
      }}
    >
      {/* Subtle background glow */}
      <Box
        sx={{
          position: "fixed",
          top: "10%",
          left: "20%",
          width: "400px",
          height: "400px",
          background:
            "radial-gradient(circle, rgba(91, 164, 245, 0.03) 0%, transparent 70%)",
          pointerEvents: "none",
          zIndex: 0,
        }}
      />
      <Box
        sx={{
          position: "fixed",
          bottom: "10%",
          right: "10%",
          width: "500px",
          height: "500px",
          background:
            "radial-gradient(circle, rgba(159, 110, 218, 0.04) 0%, transparent 70%)",
          pointerEvents: "none",
          zIndex: 0,
        }}
      />

      {/* ── Header ───────────────────────────────────────────────────────── */}
      <Stack
        direction={{ xs: "column", md: "row" }}
        justifyContent="space-between"
        alignItems={{ xs: "flex-start", md: "center" }}
        spacing={2}
        sx={{ mb: { xs: "32px", md: "48px" }, position: "relative", zIndex: 1 }}
      >
        <Box>
          <Typography
            variant="h4"
            sx={{
              fontWeight: 800,
              color: "#fff",
              fontFamily: "'Montserrat', sans-serif",
              letterSpacing: "-0.04em",
              mb: 1,
            }}
          >
            Dashboard Overview
          </Typography>
          <Typography
            variant="body2"
            sx={{
              color: "rgba(255, 255, 255, 0.4)",
              fontWeight: 500,
              fontFamily: "'Montserrat', sans-serif",
            }}
          >
            Welcome back, Admin! Here's what's happening with your app today.
          </Typography>
        </Box>
      </Stack>

      {isLoading ? (
        <Box
          sx={{
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            alignItems: "center",
            width: "100%",
            py: 12,
            gap: 2,
            position: "relative",
            zIndex: 1,
          }}
        >
          <CircularProgress size={60} thickness={4} />
        </Box>
      ) : (
        <>
          {/* ── KPI Row 1 ─────────────────────────────────────────────────────── */}
          <Box
            sx={{
              display: "flex",
              flexDirection: { xs: "column", sm: "row" },
              gap: { xs: "12px", md: "24px" },
              mb: { xs: "12px", md: "24px" },
              position: "relative",
              zIndex: 1,
            }}
          >
            {CARDS.slice(0, 3).map((card) => {
              const kpi = kpiData?.[card.key];
              const handleCardClick = card.navigable
                ? () => {
                    if (!card.statusParam) {
                      navigate('/all-users');
                    } else {
                      const qs = new URLSearchParams();
                      qs.append('status', card.statusParam);
                      if (card.subscriptionParam) {
                        qs.append('subscription', card.subscriptionParam);
                      }
                      navigate(`/all-users?${qs.toString()}`);
                    }
                  }
                : undefined;
              return (
                <KpiCard
                  key={card.key}
                  title={card.title}
                  value={kpi?.value ?? 0}
                  changePercentage={kpi?.percentage ?? 0}
                  trendDirection={kpi?.direction ?? "up"}
                  prefix={card.prefix}
                  suffix={card.suffix}
                  icon={card.icon}
                  iconColor={card.iconColor}
                  iconBg={card.iconBg}
                  onClick={handleCardClick}
                />
              );
            })}
          </Box>

          {/* ── KPI Row 2 ─────────────────────────────────────────────────────── */}
          <Box
            sx={{
              display: "flex",
              flexDirection: { xs: "column", sm: "row" },
              gap: { xs: "20px", md: "24px" },
              mb: { xs: "32px", md: "48px" },
              position: "relative",
              zIndex: 1,
            }}
          >
            {CARDS.slice(3, 6).map((card) => {
              const kpi = kpiData?.[card.key];
              return (
                <KpiCard
                  key={card.key}
                  title={card.title}
                  value={kpi?.value ?? 0}
                  changePercentage={kpi?.percentage ?? 0}
                  trendDirection={kpi?.direction ?? "up"}
                  prefix={card.prefix}
                  suffix={card.suffix}
                  icon={card.icon}
                  iconColor={card.iconColor}
                  iconBg={card.iconBg}
                />
              );
            })}
          </Box>

          {/* ── Charts: User Growth (C8) ──────────────────────────────────────── */}
          <Box
            sx={{
              display: "flex",
              flexDirection: { xs: "column", md: "row" },
              gap: { xs: "20px", md: "24px" },
              mb: { xs: "20px", md: "24px" },
              position: "relative",
              zIndex: 1,
            }}
          >
            <AreaGraph title="User Growth" data={growthChartData} lineColor="#4CC66E" selectedYear={growthYear} onYearChange={(yr) => setGrowthYear(yr)} />
          </Box>

          {/* ── Charts: User Breakdown (C9) + Subscription Tiers (C10) ─────────── */}
          <Box
            sx={{
              display: "flex",
              flexDirection: { xs: "column", md: "row" },
              gap: { xs: "20px", md: "24px" },
              mb: { xs: "20px", md: "24px" },
              position: "relative",
              zIndex: 1,
            }}
          >
            <DonutChart title="User Breakdown" data={userBreakdownData} />
            <DonutChart title="Subscription Tiers" data={subscriptionTierData} />
          </Box>

          {/* ── Charts: Avatar Interaction (Full Width) ───────────────────────── */}
          {/* <Box sx={{ width: '100%', position: 'relative', zIndex: 1, mb: { xs: '20px', md: '24px' } }}>
        <AreaGraph
          title="Avatar Engagement Trend"
          data={AVATAR_INTERACTION_DATA}
          lineColor="#9F6EDA"
          onYearChange={(yr) => console.log('Avatar interaction year:', yr)}
        />
      </Box> */}

          {/* ── Charts: AI Usage + Feature Distribution ───────────────────────────── */}
          {/* <Box
        sx={{
          display: 'flex',
          flexDirection: { xs: 'column', md: 'row' },
          gap: { xs: '20px', md: '24px' },
          position: 'relative',
          zIndex: 1,
        }}
      >
        
        <GlowBarChart
          title="AI Usage Load"
          data={AI_USAGE_DATA}
          accentColor="#5BA4F5"
          onYearChange={(yr) => console.log('AI usage year:', yr)}
        />

        
        <FeatureRadialChart
          title="Feature Usage Distribution"
          data={FEATURE_USAGE_DATA}
          onYearChange={(yr) => console.log('Feature usage year:', yr)}
        />
      </Box> */}

          {/* ── Charts: Notification Engagement (Full Width or Large Row) ────────── */}
          {/* <Box sx={{ width: '100%', position: 'relative', zIndex: 1, mt: { xs: '20px', md: '24px' } }}>
        <MultiEngagementChart
          title="Notification Engagement"
          data={NOTIFICATION_TREND_DATA}
          onYearChange={(yr) => console.log('Notification engagement year:', yr)}
        />
      </Box> */}

          {/* ── Coin purchase plans ─────────────────────────────────────────────── */}
          <CoinPlansModule
            plans={coinPlans}
            loading={isCoinPlansLoading}
            onAdd={handleOpenAddCoinPlan}
            onEdit={handleOpenEditCoinPlan}
            onDelete={(plan) => setPlanToDelete(plan)}
          />

          <Box
            sx={{
              mt: { xs: "32px", md: "48px" },
              position: "relative",
              zIndex: 1,
            }}
          >
            <DataTable
              title="Recent Users"
              columns={recentUsersColumns}
              data={recentUsers}
              isLoading={isRecentUsersLoading}
              searchTerm={recentUsersSearch}
              onSearchChange={(val) => {
                setRecentUsersSearch(val);
                setRecentUsersPage(0);
              }}
              orderBy={recentUsersOrderBy}
              order={recentUsersOrder}
              onSortChange={handleRecentUsersSort}
              pagination={{
                page: recentUsersPage,
                rowsPerPage: recentUsersPerPage,
                totalCount: recentUsersTotalCount,
                onPageChange: (_, newPage) => setRecentUsersPage(newPage),
                onRowsPerPageChange: (e) => {
                  setRecentUsersPerPage(parseInt(e.target.value, 10));
                  setRecentUsersPage(0);
                },
              }}
              emptyTitle="No recent users"
              emptyMessage="No users registered in the last 10 days."
              onViewClick={(user) => navigate(`/all-users/${user.id}`)}
              onEditClick={handleEditClick}
              onDeleteClick={handleDeleteUser}
              onNotificationClick={handleOpenNotification}
              onResetPasswordClick={handleResetPasswordClick}
            />
          </Box>
        </>
      )}

      <CoinPlanModal
        open={coinPlanModalOpen}
        onClose={() => {
          setCoinPlanModalOpen(false);
          setCoinPlanEditing(null);
        }}
        onSubmit={handleSaveCoinPlan}
        initialData={coinPlanEditing}
        loading={isSavingCoinPlan}
      />

      <ConfirmationModal
        open={Boolean(planToDelete)}
        onClose={() => setPlanToDelete(null)}
        onConfirm={handleConfirmDeletePlan}
        title="Delete coin plan?"
        message={
          planToDelete
            ? `Remove the ${planToDelete.coins} coin pack for ${Number(planToDelete.coinsPrice).toFixed(2)} ${planToDelete.currency}?`
            : ""
        }
        confirmText="Delete"
        confirmColor="error"
      />

      <ConfirmationModal
        open={openDeleteModal}
        onClose={() => setOpenDeleteModal(false)}
        onConfirm={handleConfirmDelete}
        title="Delete User?"
        message={`Are you sure you want to delete ${userToDelete?.name}? This action cannot be undone.`}
        confirmText="Delete"
        confirmColor="error"
      />

      <EditUserModal
        open={openEditModal}
        onClose={() => setOpenEditModal(false)}
        onSubmit={handleEditSubmit}
        userData={selectedUserForEdit}
        loading={isUpdatingUser}
      />

      <UserNotificationModal
        open={openNotificationModal}
        onClose={() => setOpenNotificationModal(false)}
        onSubmit={handleSendNotification}
        userData={userForNotification}
        loading={isSendingNotification}
      />

      <ResetUserPasswordModal
        open={openResetPasswordModal}
        onClose={() => {
          setOpenResetPasswordModal(false);
          setUserForPasswordReset(null);
        }}
        onSubmit={handleResetPasswordSubmit}
        userData={userForPasswordReset}
        loading={isResettingPassword}
      />
    </Box>
  );
};

export default Dashboard;
